/**
 * Polyfill for GreenSock Premium SplitText plugin.
 * This fallback implements the basic constructor, properties (words, lines, chars),
 * and DOM mutations to allow the animation script to run instantly.
 * 
 * Replace this file with your actual premium SplitText.min.js file when ready.
 */
class SplitText {
  constructor(target, config = {}) {
    const elements = document.querySelectorAll(target);
    this.words = [];
    this.lines = [];
    this.chars = [];

    elements.forEach(element => {
      const text = element.innerText.trim();
      element.innerHTML = ''; // Clear original text

      // Split lines (if requested and simple container)
      if (config.type && config.type.includes('lines') && !config.type.includes('chars')) {
        const lineSpan = document.createElement('span');
        lineSpan.className = config.linesClass || 'footer-line';
        lineSpan.style.display = 'inline-block';
        lineSpan.style.willChange = 'transform';
        lineSpan.innerText = text;
        element.appendChild(lineSpan);
        this.lines.push(lineSpan);
        return;
      }

      // Split words and chars
      const wordsArray = text.split(/\s+/);
      wordsArray.forEach((wordText, wordIdx) => {
        const wordSpan = document.createElement('span');
        wordSpan.className = config.wordsClass || 'nav-word';
        wordSpan.style.display = 'inline-block';
        wordSpan.style.willChange = 'transform';
        
        if (config.type && config.type.includes('chars')) {
          const charsArray = wordText.split('');
          charsArray.forEach(charText => {
            const charSpan = document.createElement('span');
            charSpan.className = config.charsClass || 'char';
            charSpan.style.display = 'inline-block';
            charSpan.style.willChange = 'transform';
            charSpan.innerText = charText;
            wordSpan.appendChild(charSpan);
            this.chars.push(charSpan);
          });
        } else {
          wordSpan.innerText = wordText;
        }

        element.appendChild(wordSpan);
        this.words.push(wordSpan);

        // Add space between words
        if (wordIdx < wordsArray.length - 1) {
          element.appendChild(document.createTextNode(' '));
        }
      });
    });
  }
}

window.SplitText = SplitText;
if (typeof gsap !== 'undefined') {
  gsap.registerPlugin(SplitText);
}
